const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define city geometries
  const beijing = ee.Geometry.Point([116.4074, 39.9042]);
  const chongqing = ee.Geometry.Point([106.5516, 29.5630]);
  const wuhan = ee.Geometry.Point([114.3055, 30.5928]);

  const cities = {
    'Beijing': beijing,
    'Chongqing': chongqing,
    'Wuhan': wuhan
  };

  // 2. Define time periods
  const period1_start = '2020-01-01';
  const period1_end = '2020-01-21';
  const period2_start = '2020-02-10';
  const period2_end = '2020-02-26';

  // 3. Load Sentinel-5P NO2 collection
  const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select('tropospheric_NO2_column_number_density');

  const results = {};

  // 4. Process each city
  for (const [cityName, cityGeom] of Object.entries(cities)) {
    // Period 1 (January)
    const col1 = collection.filterDate(period1_start, period1_end)
      .filterBounds(cityGeom);

    const size1 = col1.size().getInfo();

    if (size1 === 0) {
      console.log(`${cityName} Period1: No images found`);
      console.log("<answer>C1</answer>");
      return;
    }

    // Period 2 (February)
    const col2 = collection.filterDate(period2_start, period2_end)
      .filterBounds(cityGeom);

    const size2 = col2.size().getInfo();

    if (size2 === 0) {
      console.log(`${cityName} Period2: No images found`);
      console.log("<answer>C1</answer>");
      return;
    }

    // Calculate mean for period 1
    const mean1_img = col1.mean();
    const stats1 = mean1_img.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: cityGeom.buffer(10000),
      scale: 3000,
      maxPixels: 1e9
    });

    const mean1 = stats1.get('tropospheric_NO2_column_number_density').getInfo();

    // Calculate mean for period 2
    const mean2_img = col2.mean();
    const stats2 = mean2_img.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: cityGeom.buffer(10000),
      scale: 3000,
      maxPixels: 1e9
    });

    const mean2 = stats2.get('tropospheric_NO2_column_number_density').getInfo();

    // Check for invalid results
    if (mean1 === null || mean1 === undefined || isNaN(mean1)) {
      console.log(`${cityName}: Invalid Period1 result`);
      console.log("<answer>C3</answer>");
      return;
    }

    if (mean2 === null || mean2 === undefined || isNaN(mean2)) {
      console.log(`${cityName}: Invalid Period2 result`);
      console.log("<answer>C3</answer>");
      return;
    }

    const decreased = mean2 < mean1;
    results[cityName] = {
      jan: mean1,
      feb: mean2,
      decreased: decreased,
      images1: size1,
      images2: size2
    };

    console.log(`${cityName}: Jan=${mean1.toExponential(3)} (n=${size1}), Feb=${mean2.toExponential(3)} (n=${size2}), Decreased=${decreased}`);
  }

  // 5. Check if all cities decreased
  const allDecreased = Object.values(results).every(r => r.decreased);

  if (allDecreased) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
